def test_parse(run, x):
    out = run(x)
    int(out.strip())

def test_nonnegative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0

def test_lower_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    occupied = [v for v in a if v != 0]
    O = len(occupied)
    free_in_first_O = sum(1 for i in range(O) if a[i] == 0)
    ans = int(run(x).strip())
    assert ans >= free_in_first_O

def test_upper_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    occupied = [v for v in a if v != 0]
    O = len(occupied)
    ans = int(run(x).strip())
    assert ans <= O

def test_already_compact(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    occupied_seen = False
    free_after_occupied = False
    for v in a:
        if v != 0:
            occupied_seen = True
        elif occupied_seen:
            free_after_occupied = True
    # If there is no free cell after any occupied cell, it's compact
    if not free_after_occupied:
        ans = int(run(x).strip())
        assert ans == 0

def test_single_process(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    nonzeros = {v for v in a if v != 0}
    if len(nonzeros) == 1:
        # Find first occupied index (1‑based)
        for i, v in enumerate(a, start=1):
            if v != 0:
                expected = i - 1
                break
        ans = int(run(x).strip())
        assert ans == expected

def test_all_occupied(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    if all(v != 0 for v in a):
        ans = int(run(x).strip())
        assert ans == 0

def test_example1(run, x):
    if x == '4\n0 2 2 1\n':
        ans = int(run(x).strip())
        assert ans == 2

def test_example2(run, x):
    if x == '8\n0 8 8 8 0 4 4 2\n':
        ans = int(run(x).strip())
        assert ans == 4

def test_answer_le_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    ans = int(run(x).strip())
    assert ans <= n

