def test_simulation(run, x):
    # Simulate directly from input, compare output.
    # Limit to small inputs to avoid timeout.
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n * m > 10000:  # too large for brute-force simulation in a test
        return
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    # Simulate
    locked_core = [0] * n  # 0 = not locked, else cycle locked
    locked_cell = [False] * (k + 1)  # 1-indexed
    for cycle in range(1, m+1):
        writes = {}
        for i in range(n):
            if locked_core[i] != 0:
                continue
            c = instr[i][cycle-1]
            if c == 0:
                continue
            if locked_cell[c]:
                locked_core[i] = cycle
            else:
                writes.setdefault(c, []).append(i)
        # Resolve conflicts within this cycle
        for c, lst in writes.items():
            if len(lst) >= 2:
                for i in lst:
                    locked_core[i] = cycle
                locked_cell[c] = True
    # Expected outputs
    expected = [locked_core[i] for i in range(n)]
    out = run(x).strip().split()
    if len(out) != n:
        assert False
    actual = list(map(int, out))
    assert actual == expected

def test_format(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    out = run(x).strip().split('\n')
    assert len(out) == n, f"Expected {n} lines, got {len(out)}"
    for i, line in enumerate(out):
        s = line.strip()
        assert s.isdigit() or (s[0]=='-' and s[1:].isdigit()), f"Line {i+1} not an integer"
        val = int(s)
        assert 0 <= val <= m, f"Line {i+1} value {val} out of range [0, {m}]"

def test_zero_core(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    for i in range(n):
        if all(v == 0 for v in instr[i]):
            assert out[i] == 0, f"Core {i+1} has all zero instructions but output is {out[i]}"

def test_single_core(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n != 1:
        return
    out = int(run(x).strip())
    assert out == 0, f"Single core must output 0, got {out}"

def test_all_zero(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    if all(v == 0 for row in instr for v in row):
        out = list(map(int, run(x).strip().split()))
        assert all(v == 0 for v in out), f"All instructions zero but output not all zero"

def test_conflict_first_cycle(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if m == 0:
        return
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    # find cells written by >=2 cores at cycle 1
    writes = {}
    for i in range(n):
        c = instr[i][0]
        if c != 0:
            writes.setdefault(c, []).append(i)
    conflict_cores = []
    for c, lst in writes.items():
        if len(lst) >= 2:
            conflict_cores.extend(lst)
    if not conflict_cores:
        return
    out = list(map(int, run(x).strip().split()))
    for i in conflict_cores:
        assert out[i] == 1, f"Core {i+1} conflicts at cycle 1 but output is {out[i]}"

def test_unique_cell(run, x):
    # Weakened: a core that writes only to cells that no other core writes to *in the same cycle* should not deadlock.
    # Because conflict requires simultaneous write.
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    # For each core i, check if its writes are unique per cycle
    for i in range(n):
        if out[i] != 0:
            continue  # we only care about cores that are not locked
        unique = True
        for cy in range(m):
            c = instr[i][cy]
            if c == 0:
                continue
            # see if any other core writes to c at same cycle cy
            for j in range(n):
                if j == i:
                    continue
                if instr[j][cy] == c:
                    unique = False
                    break
            if not unique:
                break
        if unique:
            # core i should remain unlocked
            assert out[i] == 0, f"Core {i+1} writes to unique cells per cycle but output is {out[i]}"

def test_locking_cycle_nonzero(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    for i in range(n):
        t = out[i]
        if t > 0:
            # cycle numbers are 1‑based
            assert 1 <= t <= m
            # instruction at that cycle must be non‑zero
            assert instr[i][t-1] != 0, f"Core {i+1} deadlocks at cycle {t} but instruction is zero"

def test_cell_locking_consistency(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    # For each cell c, collect (cycle, core) pairs where core deadlocks writing to c
    deadlocks_per_cell = {c: [] for c in range(1, k+1)}
    for i in range(n):
        t = out[i]
        if t > 0:
            c = instr[i][t-1]
            if c != 0:
                deadlocks_per_cell[c].append((t, i))
    for c in range(1, k+1):
        lst = deadlocks_per_cell[c]
        if len(lst) < 2:
            continue
        # earliest cycle among them
        earliest = min(t for t, _ in lst)
        # at that earliest cycle, must have at least two cores deadlocking with that cell
        count = sum(1 for t, _ in lst if t == earliest)
        assert count >= 2, f"Cell {c} has deadlocks but earliest cycle {earliest} has only one core"

def test_consistency(run, x):
    # Use output to reconstruct locking and verify it matches the specification.
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n * m > 10000:
        return  # skip large inputs to keep test fast
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    # Simulate using the output to know when cores are locked.
    locked_core = [0] * n
    locked_cell = [False] * (k + 1)
    for cycle in range(1, m+1):
        writes = {}
        for i in range(n):
            if locked_core[i] != 0:
                continue
            c = instr[i][cycle-1]
            if c == 0:
                continue
            if locked_cell[c]:
                # core should deadlock now if output says so
                if out[i] == cycle:
                    locked_core[i] = cycle
                else:
                    # output says it doesn't deadlock now, but cell is locked -> impossible
                    assert False, f"Core {i+1} writes to locked cell {c} at cycle {cycle} but output says no deadlock"
            else:
                writes.setdefault(c, []).append(i)
        # Resolve conflicts
        for c, lst in writes.items():
            if len(lst) >= 2:
                for i in lst:
                    if out[i] == cycle:
                        locked_core[i] = cycle
                    else:
                        assert False, f"Core {i+1} conflicts on cell {c} at cycle {cycle} but output says no deadlock"
                locked_cell[c] = True
            else:
                # single writer, should not deadlock now
                i = lst[0]
                if out[i] == cycle:
                    assert False, f"Core {i+1} alone writes to cell {c} at cycle {cycle} but output says deadlock"
    # After simulation, check that all outputs match our computed locked_core
    for i in range(n):
        assert locked_core[i] == out[i], f"Core {i+1} simulation mismatch: expected {locked_core[i]}, got {out[i]}"

