def test_exact_simulation(run, x):
    # Simulate the processor exactly for small inputs (n,m,k <= 100, but we limit for speed).
    # Since n,m,k <= 100, simulation is O(n*m*k) = 1e6 worst-case, acceptable.
    lines = x.strip().split('\n')
    n_m_k = list(map(int, lines[0].split()))
    n, m, k = n_m_k
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = run(x).strip().split('\n')
    if len(out) != n:
        raise AssertionError('Output line count mismatch')
    out_vals = [int(v) for v in out]
    # simulation
    locked_core = [False]*n
    locked_cell = [False]*k
    lock_cycle = [0]*n
    for cycle in range(1, m+1):
        # cell -> list of cores writing this cycle
        writes = {}
        for i in range(n):
            if locked_core[i]:
                continue
            c = instr[i][cycle-1]
            if c != 0:
                writes.setdefault(c-1, []).append(i)
        # process conflicts
        for cell_idx, writers in writes.items():
            if locked_cell[cell_idx]:
                # cell already locked, lock all writers now
                for i in writers:
                    if not locked_core[i]:
                        locked_core[i] = True
                        lock_cycle[i] = cycle
            else:
                if len(writers) >= 2:
                    # conflict: lock cell and all writers
                    locked_cell[cell_idx] = True
                    for i in writers:
                        if not locked_core[i]:
                            locked_core[i] = True
                            lock_cycle[i] = cycle
        # after conflicts, any single writer to an unlocked cell succeeds (no lock)
        # but if a writer writes to a cell that became locked this same cycle due to
        # a conflict on that cell, it was already locked above.
        # Actually spec: if multiple cores write to a cell in the same cycle, deadlock.
        # If a single core writes to an unlocked cell, no lock.
        # So we already handled all locks above.
    # compare
    for i in range(n):
        if lock_cycle[i] != out_vals[i]:
            raise AssertionError(f'Core {i+1}: expected {lock_cycle[i]}, got {out_vals[i]}')

def test_output_format(run, x):
    lines = x.strip().split('\n')
    n_m_k = list(map(int, lines[0].split()))
    n = n_m_k[0]
    out = run(x).strip().split('\n')
    if len(out) != n:
        raise AssertionError('Output line count mismatch')
    for i, line in enumerate(out):
        v = line.strip()
        if not v.isdigit() and (v[0]=='-' and v[1:].isdigit()):
