    out_vals = [int(v) for v in out]
    # Compute cell locking cycles: cell becomes locked at cycle t if there exists a conflict at t on that cell.
    cell_lock_cycle = [m+1]*k  # large if never locked
    for t in range(1, m+1):
        # find conflicts at t using output: cores locking at t with same cell
        cell_to_lockers = {}
        for i in range(n):
            if out_vals[i] == t:
                c = instr[i][t-1]
                if c == 0:
                    continue
                cell_to_lockers.setdefault(c, []).append(i)
        for c, lst in cell_to_lockers.items():
            if len(lst) >= 2:
                cell_lock_cycle[c-1] = min(cell_lock_cycle[c-1], t)
    # For each core locked at cycle t, check earlier cycles j < t where it wrote to cell c: cell must not have been locked at start of j.
    for i in range(n):
        t = out_vals[i]
        if t == 0:
