    a = [list(map(int, lines[i+1].split())) for i in range(n)]
    # Check adjacent non‑zero cells.
    impossible = False
    for i in range(n):
        for j in range(m-1):
            if a[i][j] != 0 and a[i][j+1] != 0 and a[i][j] >= a[i][j+1]:
                impossible = True
    for i in range(n-1):
        for j in range(m):
            if a[i][j] != 0 and a[i+1][j] != 0 and a[i][j] >= a[i+1][j]:
                impossible = True
    if impossible:
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            return
        assert val == -1, "Adjacent fixed cells violate increasing order, answer must be -1"

def test_local_bounds(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m[0], n_m[1]
    a = [list(map(int, lines[i+1].split())) for i in range(n)]
    impossible = False
    for i in range(1, n-1):
        for j in range(1, m-1):
            if a[i][j] == 0:
                left = a[i][j-1]
                right = a[i][j+1]
                top = a[i-1][j]
                bottom = a[i+1][j]
                # Only consider non‑zero neighbors for bounds.
                low = 1
                high = 10**9
                if left != 0:
                    low = max(low, left + 1)
                if top != 0:
                    low = max(low, top + 1)
                if right != 0:
                    high = min(high, right - 1)
                if bottom != 0:
                    high = min(high, bottom - 1)
                if low > high:
                    impossible = True
    if impossible:
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            return
        assert val == -1, "Local interval empty for some zero, answer must be -1"

def test_LU_consistency(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m[0], n_m[1]
    a = [list(map(int, lines[i+1].split())) for i in range(n)]
    # Compute L and U assuming zeros can be filled arbitrarily.
    L = [[0]*m for _ in range(n)]
    U = [[0]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if a[i][j] != 0:
                L[i][j] = a[i][j]
                U[i][j] = a[i][j]
            else:
                L[i][j] = 1
                U[i][j] = 10**9
    # Propagate L from top‑left.
    for i in range(n):
        for j in range(m):
            if i > 0:
                L[i][j] = max(L[i][j], L[i-1][j] + 1)
            if j > 0:
                L[i][j] = max(L[i][j], L[i][j-1] + 1)
    # Propagate U from bottom‑right.
    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            if i+1 < n:
                U[i][j] = min(U[i][j], U[i+1][j] - 1)
            if j+1 < m:
                U[i][j] = min(U[i][j], U[i][j+1] - 1)
    consistent = all(L[i][j] <= U[i][j] for i in range(n) for j in range(m))
    if not consistent:
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            return
        assert val == -1, "L > U for some cell, answer must be -1"

