def test_greedy_valid_consistency(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m[0], n_m[1]
    a = [list(map(int, lines[i+1].split())) for i in range(n)]
    # Make a copy for greedy filling.
    b = [row[:] for row in a]
    # Process cells in reverse order.
    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            if b[i][j] == 0:
                cand = 10**9
                if i+1 < n:
                    cand = min(cand, b[i+1][j] - 1)
                if j+1 < m:
                    cand = min(cand, b[i][j+1] - 1)
                # If both neighbors are zero? The plan's greedy sets to min(bottom,right)-1.
                # In reverse order, bottom/right are already filled.
                if cand == 10**9:
                    cand = 1  # should not happen for internal zeros given constraints
                b[i][j] = cand
    # Check if resulting matrix is strictly increasing.
    def is_increasing(mat):
        for i in range(n):
            for j in range(m-1):
                if mat[i][j] >= mat[i][j+1]:
                    return False
        for j in range(m):
            for i in range(n-1):
                if mat[i][j] >= mat[i+1][j]:
                    return False
        return True
    if is_increasing(b):
        expected = sum(sum(row) for row in b)
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            return
        assert val == expected, f"Greedy yields valid increasing matrix, sum must be {expected}"

