tests_src:
def test_correct(run, x):
    # Parse year, month, day from input string.
    y, m, d = map(int, x.strip().split('/'))
    # Compute expected answer based on spec: if (year, month, day) <= (2019, 4, 30) -> Heisei else TBD
    expected = 'Heisei\n' if (y, m, d) <= (2019, 4, 30) else 'TBD\n'
    assert run(x) == expected

def test_output_format(run, x):
    output = run(x)
    assert output in ('Heisei\n', 'TBD\n')

def test_month_le4_heisei(run, x):
    month = int(x.strip().split('/')[1])
    if month <= 4:
        assert run(x) == 'Heisei\n'

def test_month_gt4_tbd(run, x):
    month = int(x.strip().split('/')[1])
    if month > 4:
        assert run(x) == 'TBD\n'

def test_april30_boundary(run, x):
    y, m, d = map(int, x.strip().split('/'))
    if (y, m, d) == (2019, 4, 30):
        assert run(x) == 'Heisei\n'

def test_may1_boundary(run, x):
    y, m, d = map(int, x.strip().split('/'))
    if (y, m, d) == (2019, 5, 1):
        assert run(x) == 'TBD\n'

def test_output_length(run, x):
    output = run(x)
    assert len(output) in (7, 4)  # 'Heisei\n' is 7 chars, 'TBD\n' is 4

def test_output_starts_with_h_or_t(run, x):
    output = run(x)
    assert output.startswith('H') or output.startswith('T')

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n')

def test_output_no_extra_whitespace(run, x):
    output = run(x)
    trimmed = output.rstrip('\n')
    import string
    assert all(c not in string.whitespace for c in trimmed)

