def test_example1(run, x):
    if x == "3\n1\n1\n2\n":
        out = run(x)
        assert out == "YES\n"

def test_example2(run, x):
    if x == "2\n1\n2\n":
        out = run(x)
        assert out == "NO\n"

def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped == "YES" or stripped == "NO"

def test_first_winner_3(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        first_winner = int(lines[1])
        if first_winner == 3:
            out = run(x)
            assert out.strip() == "NO"

def test_all_winners_3(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        winners = list(map(int, lines[1:]))
        if all(w == 3 for w in winners):
            out = run(x)
            assert out.strip() == "NO"

def test_single_game_1_or_2(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 2:
        winner = int(lines[1])
        if winner == 1 or winner == 2:
            out = run(x)
            assert out.strip() == "YES"

def test_single_game_3(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 2:
        winner = int(lines[1])
        if winner == 3:
            out = run(x)
            assert out.strip() == "NO"

def test_simulation(run, x):
    # Only simulate for n <= 100 (as per spec) and input size small enough
    lines = x.strip().split('\n')
    if len(lines) > 1:
        n = int(lines[0])
        winners = list(map(int, lines[1:1+n]))
        spec = 3
        possible = True
        for w in winners:
            if w == spec:
                possible = False
                break
            spec = 6 - w - spec
        out = run(x)
        if possible:
            assert out.strip() == "YES"
        else:
            assert out.strip() == "NO"

def test_second_game_condition(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 3:
        n = int(lines[0])
        if n >= 2:
            first = int(lines[1])
            second = int(lines[2])
            loser_of_first = 6 - first - 3
            out = run(x)
            if out.strip() == "YES":
                assert second != loser_of_first

def test_no_winner_equals_spec_anytime(run, x):
    lines = x.strip().split('\n')
    if len(lines) > 1:
        n = int(lines[0])
        winners = list(map(int, lines[1:1+n]))
        spec = 3
        out = run(x)
        if out.strip() == "YES":
            for w in winners:
                assert w != spec
                spec = 6 - w - spec

