def test_correct(run, x):
    # Parse input
    lines = x.strip('\n').split('\n')
    if len(lines) < 2:
        return  # invalid, no assertion
    table = lines[0].strip()
    hand = lines[1].strip().split()
    # Check constraints
    ranks = set('23456789TJQKA')
    suits = set('DCSH')
    if len(table) != 2 or table[0] not in ranks or table[1] not in suits:
        return
    if len(hand) != 5:
        return
    cards = set([table] + hand)
    if len(cards) != 6:
        return  # duplicates
    for c in hand:
        if len(c) != 2 or c[0] not in ranks or c[1] not in suits:
            return
    # Input is valid per spec, compute expected answer
    can_play = False
    for c in hand:
        if c[0] == table[0] or c[1] == table[1]:
            can_play = True
            break
    expected = 'YES' if can_play else 'NO'
    out = run(x).strip().upper()
    assert out == expected

def test_format(run, x):
    out = run(x)
    if out.endswith('\n'):
        out = out[:-1]
    out_upper = out.upper()
    assert out_upper in ('YES', 'NO'), f"Output must be YES or NO, got {out}"
    # No extra characters
    assert out.isalpha() or (out == ''), f"Output contains non‑letters"

def test_example1(run, x):
    if x == 'AS\n2H 4C TH JH AD\n':
        out = run(x).strip().upper()
        assert out == 'YES'

def test_example2(run, x):
    if x == '2H\n3D 4C AC KD AS\n':
        out = run(x).strip().upper()
        assert out == 'NO'

def test_example3(run, x):
    if x == '4D\nAS AC AD AH 5H\n':
        out = run(x).strip().upper()
        assert out == 'YES'

def test_rank_match(run, x):
    # Parse and validate
    lines = x.strip('\n').split('\n')
    if len(lines) < 2:
        return
    table = lines[0].strip()
    hand = lines[1].strip().split()
    ranks = set('23456789TJQKA')
    suits = set('DCSH')
    if len(table) != 2 or table[0] not in ranks or table[1] not in suits:
        return
    if len(hand) != 5:
        return
    cards = set([table] + hand)
    if len(cards) != 6:
        return
    for c in hand:
        if len(c) != 2 or c[0] not in ranks or c[1] not in suits:
            return
    # Check if at least one hand card has same rank
    rank_match = any(c[0] == table[0] for c in hand)
    if rank_match:
        out = run(x).strip().upper()
        assert out == 'YES'

def test_suit_match(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) < 2:
        return
    table = lines[0].strip()
    hand = lines[1].strip().split()
    ranks = set('23456789TJQKA')
    suits = set('DCSH')
    if len(table) != 2 or table[0] not in ranks or table[1] not in suits:
        return
    if len(hand) != 5:
        return
    cards = set([table] + hand)
    if len(cards) != 6:
        return
    for c in hand:
        if len(c) != 2 or c[0] not in ranks or c[1] not in suits:
            return
    suit_match = any(c[1] == table[1] for c in hand)
    if suit_match:
        out = run(x).strip().upper()
        assert out == 'YES'

def test_no_match(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) < 2:
        return
    table = lines[0].strip()
    hand = lines[1].strip().split()
    ranks = set('23456789TJQKA')
    suits = set('DCSH')
    if len(table) != 2 or table[0] not in ranks or table[1] not in suits:
        return
    if len(hand) != 5:
        return
    cards = set([table] + hand)
    if len(cards) != 6:
        return
    for c in hand:
        if len(c) != 2 or c[0] not in ranks or c[1] not in suits:
            return
    rank_ok = all(c[0] != table[0] for c in hand)
    suit_ok = all(c[1] != table[1] for c in hand)
    if rank_ok and suit_ok:
        out = run(x).strip().upper()
        assert out == 'NO'

def test_length(run, x):
    out = run(x)
    if out.endswith('\n'):
