tests_src:
def test_line_count(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    output = run(x).strip().split('\n')
    assert len(output) == n, f'Expected {n} output lines, got {len(output)}'

def test_allowed_strings(run, x):
    output = run(x).strip().split('\n')
    allowed = {'Freda\'s', 'Rainbow\'s', 'OMG>.< I don\'t know!'}
    for line in output:
        assert line in allowed, f'Invalid output line: {line}'

def test_freda_condition(run, x):
    lines = x.strip().split('\n')[1:]
    output = run(x).strip().split('\n')
    for s, out in zip(lines, output):
        if s.endswith('lala.') and not s.startswith('miao.'):
            assert out == 'Freda\'s', f'Freda condition failed for: {s}'

def test_rainbow_condition(run, x):
    lines = x.strip().split('\n')[1:]
    output = run(x).strip().split('\n')
    for s, out in zip(lines, output):
        if s.startswith('miao.') and not s.endswith('lala.'):
            assert out == 'Rainbow\'s', f'Rainbow condition failed for: {s}'

def test_both_condition(run, x):
    lines = x.strip().split('\n')[1:]
    output = run(x).strip().split('\n')
    for s, out in zip(lines, output):
        if s.startswith('miao.') and s.endswith('lala.'):
            assert out == 'OMG>.< I don\'t know!', f'Both condition failed for: {s}'

def test_neither_condition(run, x):
    lines = x.strip().split('\n')[1:]
    output = run(x).strip().split('\n')
    for s, out in zip(lines, output):
        if not s.startswith('miao.') and not s.endswith('lala.'):
            assert out == 'OMG>.< I don\'t know!', f'Neither condition failed for: {s}'

def test_exact_lala(run, x):
    lines = x.strip().split('\n')[1:]
    output = run(x).strip().split('\n')
    for s, out in zip(lines, output):
        if s == 'lala.':
            assert out == 'Freda\'s', f'Exact lala. failed for: {s}'

def test_exact_miao(run, x):
    lines = x.strip().split('\n')[1:]
    output = run(x).strip().split('\n')
    for s, out in zip(lines, output):
        if s == 'miao.':
            assert out == 'Rainbow\'s', f'Exact miao. failed for: {s}'

def test_exact_miao_lala(run, x):
    lines = x.strip().split('\n')[1:]
    output = run(x).strip().split('\n')
    for s, out in zip(lines, output):
        if s == 'miao.lala.':
            assert out == 'OMG>.< I don\'t know!', f'Exact miao.lala. failed for: {s}'

def test_duplicate_consistency(run, x):
    lines = x.strip().split('\n')[1:]
    output = run(x).strip().split('\n')
    seen = {}
    for s, out in zip(lines, output):
        if s in seen:
            assert seen[s] == out, f'Duplicate sentence {s} got different outputs'
        else:
            seen[s] = out

