{
  "rationale": "These tests check necessary conditions derived from the problem statement: the output must be an integer within bounds, must satisfy lower bounds from extreme beds and gaps, must be sufficient to cover all beds, must be minimal, and must match direct computation. Special cases are also verified. The most expensive but definitive test is test_direct, which would be the first to drop if performance were an issue, as the others together provide strong checks.",
  "plan": [
    {
      "name": "test_integer",
      "intent": "The output must be a single integer. Parse the output string as an integer; if parsing fails or there are extra characters, the answer is wrong."
    },
    {
      "name": "test_bounds",
      "intent": "The output integer must be between 1 and n inclusive. If it is less than 1 or greater than n, the answer is wrong."
    },
    {
      "name": "test_leftmost_bound",
      "intent": "Compute the minimum distance from bed 1 to any tap: d = min(|1 - tap|). The output must be at least d+1, because bed 1 needs that many seconds to be watered."
    },
    {
      "name": "test_rightmost_bound",
      "intent": "Compute the minimum distance from bed n to any tap: d = min(|n - tap|). The output must be at least d+1."
    },
    {
      "name": "test_gap_bound",
      "intent": "For each pair of consecutive taps (sorted), let gap = right - left. Compute needed = ceil((gap+1)/2). The output must be at least needed for the beds between them to be watered in time."
    },
    {
      "name": "test_combined_lower_bound",
      "intent": "Compute L = maximum of the values from tests 3,4,5. The output must be at least L."
    },
    {
      "name": "test_sufficiency",
      "intent": "Let t = output. For each bed i from 1 to n, compute the minimum distance to any tap, d_i. Assert that d_i ≤ t-1. If any bed has d_i > t-1, then t is too small and the answer is wrong."
    },
    {
      "name": "test_minimality",
      "intent": "Let t = output. If t == 1, assert that every bed has a tap (k == n). Otherwise, compute d_i for each bed, and assert that there exists at least one bed i such that d_i ≥ t-1. If no such bed exists, then t-1 would also suffice, so t is not minimal and the answer is wrong."
    },
    {
      "name": "test_direct",
      "intent": "Compute the correct answer directly: for each bed i, compute d_i = min distance to any tap, then compute M = max_i d_i + 1. Assert that output equals M."
    },
    {
      "name": "test_special_cases",
      "intent": "If all beds have taps (k == n), assert output == 1. If there is exactly one tap (k == 1), let p be that tap position, assert output == max(p, n-p+1)."
    }
  ]
}

{
  "rationale": "The tests verify the output against necessary conditions from the specification: valid integer, bounds, achievability, and maximality. Special cases (K ≤ A, A < K ≤ A+B, K > A+B, and K = total cards) catch branch-specific errors. A brute-force check for small inputs provides direct verification. The parity test for B=0 catches parity inconsistencies. The bounds test ensures the answer lies within the theoretical minimum and maximum sums. The achievability and maximality tests together ensure the answer is the maximum achievable sum. If a test must be dropped, the simple bounds test is the least informative as it is subsumed by achievability.",
  "plan": [
    {
      "name": "test_integer",
      "intent": "Check that the output is a valid integer. Violation: the output string cannot be parsed as an integer."
    },
    {
      "name": "test_bounds_tighter",
      "intent": "Check that the answer lies between -min(C,K) and min(A,K). Violation: the answer is less than -min(C,K) or greater than min(A,K)."
    },
    {
      "name": "test_achievable",
      "intent": "Check that the reported sum can be achieved by picking exactly K cards from the multiset of A ones, B zeros, and C negative ones. Violation: no combination of up to A ones, B zeros, and C negative ones that totals K cards yields the given sum."
    },
    {
      "name": "test_maximal",
      "intent": "Check that the reported sum is the maximum achievable by verifying that increasing it by 1 would not be achievable. Violation: either the reported sum is not achievable, or the sum plus one is achievable."
    },
    {
      "name": "test_special_K_le_A",
      "intent": "If K ≤ A, the answer must equal K because we can take K ones and cannot exceed K. Violation: K ≤ A and answer ≠ K."
    },
    {
      "name": "test_special_A_lt_K_le_AplusB",
      "intent": "If A < K ≤ A+B, the answer must equal A because we take all ones and fill the rest with zeros. Violation: A < K ≤ A+B and answer ≠ A."
    },
    {
      "name": "test_special_K_gt_AplusB",
      "intent": "If K > A+B, the answer must equal 2A + B - K because we take all ones and zeros, and the rest are negative ones. Violation: K > A+B and answer ≠ 2A + B - K."
    },
    {
      "name": "test_all_cards",
      "intent": "If K equals the total number of cards (A+B+C), the answer must equal A - C because we take every card. Violation: K = A+B+C and answer ≠ A - C."
    },
    {
      "name": "test_small_brute_force",
      "intent": "For inputs where the total number of cards (A+B+C) is at most 30, compute the maximum sum by brute force enumeration of all possible selections of K cards and compare with the answer. Violation: answer differs from the brute-force maximum."
    },
    {
      "name": "test_parity_B_zero",
      "intent": "When there are no zero cards (B=0), the difference between K and the answer must be even, because the number of negative ones taken is (K - answer)/2. Violation: B=0 and (K - answer) is odd."
    }
  ]
}

