    },
    {
      "name": "test_upper_bound",
      "intent": "If the output is a non-negative integer k, check that k < n. Since the maximum distance in a permutation is n-1, any k ≥ n is impossible. Violation: k ≥ n."
    },
    {
      "name": "test_s_equal_t",
      "intent": "If the initial position s equals the target position t, the output must be 0. Violation: s == t but output is not 0."
