def test_bruteforce_small_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 8:
        return
    a = list(map(int, lines[1].split()))
    from collections import deque
    start = tuple((i, a[i]) for i in range(n))
    target_states = set()
    for pillar in range(n):
        state = []
        for i in range(n):
            if i == pillar:
                state.append((i, a[i]))
            else:
                state.append((i, None))
        # Represent as tuples of (disk radius or None) on each pillar
        target = tuple(a[i] if i == pillar else None for i in range(n))
        target_states.add(target)
    visited = {start}
    q = deque([start])
    while q:
        state = q.popleft()
        # Convert to list of pillars each with a list of disks (bottom to top)
        pillars = [[] for _ in range(n)]
        for i, rad in state:
            if rad is not None:
                pillars[i].append(rad)
        for i in range(n):
            if not pillars[i]:
                continue
            top = pillars[i][-1]
            for nb in (i-1, i+1):
                if 0 <= nb < n:
                    if not pillars[nb] or pillars[nb][-1] > top:
                        new_pillars = [list(col) for col in pillars]
                        new_pillars[i].pop()
                        new_pillars[nb].append(top)
                        new_state = []
                        for idx in range(n):
                            if new_pillars[idx]:
                                for rad in new_pillars[idx]:
                                    new_state.append((idx, rad))
                            else:
                                new_state.append((idx, None))
                        new_state = tuple(new_state)
                        if new_state not in visited:
                            visited.add(new_state)
                            q.append(new_state)
    reachable_target = any(targ in visited for targ in target_states)
    out = run(x)
    expected = 'YES\n' if reachable_target else 'NO\n'
    assert out.upper() == expected.upper()

def test_output_format(run, x):
    import re
    out = run(x)
    assert re.fullmatch(r'(?i)^(YES|NO)\n$', out) is not None

def test_n3_special(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 3:
        return
    a = list(map(int, lines[1].split()))
    out = run(x)
    pos_of_1 = a.index(1) + 1  # 1‑based index
    expected = 'YES\n' if pos_of_1 == 1 or pos_of_1 == n else 'NO\n'
    assert out.upper() == expected.upper()

def test_monotonic_yes(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    inc = all(a[i] < a[i+1] for i in range(len(a)-1))
    dec = all(a[i] > a[i+1] for i in range(len(a)-1))
    if inc or dec:
        out = run(x)
        assert out.upper() == 'YES\n'

def test_no_extra_whitespace(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n', 'yes\n', 'no\n', 'Yes\n', 'No\n')
    # Additional strictness: no spaces before/after
    assert out.strip() in ('YES', 'NO', 'yes', 'no', 'Yes', 'No')
    assert out == out.strip() + '\n'

def test_sufficient_condition(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # Compute sorted indices descending by radius
    indices = sorted(range(n), key=lambda i: a[i], reverse=True)
    L = R = indices[0]
    ok = True
    for idx in indices[1:]:
        if idx == L - 1:
            L = idx
        elif idx == R + 1:
            R = idx
        else:
            ok = False
            break
    if ok:
        out = run(x)
        assert out.upper() == 'YES\n'

def test_examples(run, x):
    if x == '4\n1 3 4 2\n':
        out = run(x)
        assert out.upper() == 'YES\n'
    if x == '3\n3 1 2\n':
        out = run(x)
        assert out.upper() == 'NO\n'

def test_output_uppercase(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n')

def test_input_integrity(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    assert n == len(a)
    assert len(set(a)) == n
    assert min(a) == 1
    assert max(a) == n
    # Run to ensure output exists, but no assertion on output content
    _ = run(x)

def test_n_range(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    assert 3 <= n <= 200000
    _ = run(x)

