def test_brute_force(run, x):
    import itertools
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n > 10:
        return
    trees = []
    for i in range(1, n+1):
        xi, hi = map(int, lines[i].split())
        trees.append((xi, hi))
    best = 0
    for choices in itertools.product([-1,0,1], repeat=n): # -1 left, 0 skip, 1 right
        occupied = []
        ok = True
        count = 0
        for (xi, hi), c in zip(trees, choices):
            if c == -1:
                seg = (xi - hi, xi)
            elif c == 1:
                seg = (xi, xi + hi)
            else:
                seg = (xi, xi)
            for occ in occupied:
                if occ[0] <= seg[0] <= occ[1] or occ[0] <= seg[1] <= occ[1] or (seg[0] <= occ[0] and seg[1] >= occ[1]):
                    ok = False
                    break
            if not ok:
                break
            occupied.append(seg)
            if c != 0:
                count += 1
        if ok and count > best:
            best = count
    ans = int(run(x).strip())
    assert ans == best, f"Brute force optimal is {best}, got {ans}"

def test_bounds(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    ans_str = run(x).strip()
    ans = int(ans_str)
    assert 1 <= ans <= n, f"Answer {ans} not in [1, {n}]"

def test_example1(run, x):
    example = "5\n1 2\n2 1\n5 10\n10 9\n19 1\n"
    if x == example:
        ans = run(x).strip()
        assert ans == "3", f"Example 1 expects 3, got {ans}"

def test_example2(run, x):
    example = "5\n1 2\n2 1\n5 10\n10 9\n20 1\n"
    if x == example:
        ans = run(x).strip()
        assert ans == "4", f"Example 2 expects 4, got {ans}"

def test_greedy(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    trees = []
    for i in range(1, n+1):
        xi, hi = map(int, lines[i].split())
        trees.append((xi, hi))
    occupied = []
    count = 0
    for xi, hi in trees:
        # try left
        left = xi - hi
        right = xi + hi
        left_ok = True
        if occupied:
            last = occupied[-1]
            if last[0] <= left <= last[1] or last[0] <= xi <= last[1] or (left <= last[0] and xi >= last[1]):
                left_ok = False
        if left_ok and (not occupied or left > occupied[-1][1]):
            occupied.append((left, xi))
            count += 1
            continue
        # try right
        right_ok = True
        if occupied:
            last = occupied[-1]
            if last[0] <= xi <= last[1] or last[0] <= right <= last[1] or (xi <= last[0] and right >= last[1]):
                right_ok = False
        if right_ok and (not occupied or xi > occupied[-1][1]):
            occupied.append((xi, right))
            count += 1
            continue
        # skip
        occupied.append((xi, xi))
    ans = int(run(x).strip())
    assert ans >= count, f"Greedy gives {count}, answer {ans} is smaller"

def test_all_cut_sufficient(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    trees = []
    for i in range(1, n+1):
        xi, hi = map(int, lines[i].split())
        trees.append((xi, hi))
    all_cut_possible = True
    for i in range(n-1):
        if trees[i][0] + trees[i][1] >= trees[i+1][0]:
            all_cut_possible = False
            break
    if all_cut_possible:
        ans = int(run(x).strip())
        assert ans == n, f"All trees can be cut, expected {n}, got {ans}"

def test_left_greedy_lower_bound(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    trees = []
    for i in range(1, n+1):
        xi, hi = map(int, lines[i].split())
        trees.append((xi, hi))
    last = -float('inf')
    count = 0
    for xi, hi in trees:
        left = xi - hi
        if left > last:
            count += 1
            last = xi
        else:
            last = max(last, xi)
    ans = int(run(x).strip())
    assert ans >= count, f"Left greedy lower bound is {count}, answer {ans} is smaller"

def test_right_greedy_lower_bound(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    trees = []
    for i in range(1, n+1):
        xi, hi = map(int, lines[i].split())
        trees.append((xi, hi))
    last = -float('inf')
    count = 0
    for i, (xi, hi) in enumerate(trees):
        right = xi + hi
        if i == n-1:
            if xi > last:
                count += 1
                last = right
            else:
                last = max(last, xi)
        else:
            next_x = trees[i+1][0]
            if xi > last and right < next_x:
                count += 1
                last = right
            else:
                last = max(last, xi)
    ans = int(run(x).strip())
    assert ans >= count, f"Right greedy lower bound is {count}, answer {ans} is smaller"

def test_output_format(run, x):
    ans_str = run(x)
    assert ans_str.strip().isdigit(), f"Output '{ans_str}' is not a non‑negative integer"
    # optional trailing newline allowed, nothing else
    if ans_str != ans_str.strip():
        assert ans_str == ans_str.strip() + '\n', f"Extra whitespace besides newline"

def test_at_least_one(run, x):
    ans = int(run(x).strip())
    assert ans >= 1, f"Answer {ans} less than 1"

