        if line != stripped:
            raise AssertionError(f'Extra whitespace on line {i}: {repr(line)}')

def test_simulation(run, x):
    # Only run simulation if input size and time values are small enough.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 1000:
        return  # too large, skip
    # check if any time > 1e6 (heuristic to avoid huge ranges)
    max_time = 0
    for line in lines[1:1+n]:
        parts = line.split()
        if len(parts) < 3:
            continue
        t = int(parts[1])
        if t > 1_000_000:
            return  # skip large times
    # simulate
    ops = []
    for line in lines[1:1+n]:
        parts = line.split()
        a, t, x_val = int(parts[0]), int(parts[1]), int(parts[2])
        ops.append((t, a, x_val))
    ops.sort(key=lambda z: z[0])  # sort by time
    counts = {}
    expected = []
    for t, a, x_val in ops:
        if a == 1:
            counts[x_val] = counts.get(x_val, 0) + 1
        elif a == 2:
            counts[x_val] = counts.get(x_val, 0) - 1
        else:  # a == 3
            expected.append(counts.get(x_val, 0))
    output = run(x)
    out_lines = output.strip().split('\n')
    if output.strip() == '':
        out_lines = []
    assert len(out_lines) == len(expected), f'Simulation expects {len(expected)} answers, got {len(out_lines)}'
    for i, (out_str, exp) in enumerate(zip(out_lines, expected)):
        out_val = int(out_str.strip())
        assert out_val == exp, f'Output {i}: expected {exp}, got {out_val}'

