def test_exact(run, x):
    lines = x.splitlines()
    n = int(lines[0])
    out = run(x)
    if n == 1:
        assert out == 'Hello World\n'
    else:
        a = int(lines[1])
        b = int(lines[2])
        assert int(out.strip()) == a + b

def test_format(run, x):
    out = run(x)
    assert out.endswith('\n')
    content = out.rstrip('\n')
    n = int(x.splitlines()[0])
    if n == 1:
        assert content == 'Hello World'
    else:
        # Must be a non‑empty string of digits, and represent a number
        assert content.isdigit() and len(content) > 0
        # Additionally, the number must be between 2 and 18 (from constraints A,B in 1..9)
        val = int(content)
        assert 2 <= val <= 18

def test_n1_hello(run, x):
    if x.startswith('1'):
        out = run(x)
        assert out.rstrip('\n') == 'Hello World'

def test_n2_range(run, x):
    if x.startswith('2'):
        out = run(x)
        s = out.strip()
        val = int(s)
        assert 2 <= val <= 18

def test_newline(run, x):
    out = run(x)
    assert out.endswith('\n')

def test_no_spaces(run, x):
    out = run(x)
    # No space or tab in the whole output (including before newline)
    assert ' ' not in out and '\t' not in out

def test_length(run, x):
    out = run(x)
    n = int(x.splitlines()[0])
    if n == 1:
        # Must be exactly 'Hello World' plus newline → length 12
        assert len(out) == 12
    else:
        content = out.strip()
        # Must be 1 or 2 digits because A,B in 1..9 → sum 2..18
        assert len(content) in (1, 2)

