tests_src:
def test_valid_choice(run, x):
    output = run(x).strip()
    assert output in ('1', '2', '3'), 'Output must be exactly one of 1, 2, or 3 (after stripping whitespace).'

def test_integer(run, x):
    output = run(x).strip()
    try:
        int(output)
    except ValueError:
        raise AssertionError('Output must be a parsable integer.')

def test_range(run, x):
    output = run(x).strip()
    val = int(output)
    assert 1 <= val <= 3, 'Output integer must be 1, 2, or 3.'

def test_not_A(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 1:
        try:
            A = int(lines[0].strip())
            output = int(run(x).strip())
            assert output != A, 'Output must not equal A (choice A is wrong).'
        except ValueError:
            pass  # If A is not an integer, the problem statement doesn't apply, so skip.


def test_not_B(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        try:
            B = int(lines[1].strip())
            output = int(run(x).strip())
            assert output != B, 'Output must not equal B (choice B is wrong).'
        except ValueError:
            pass  # If B is not an integer, skip.


def test_correct_for_valid(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        try:
            A = int(lines[0].strip())
            B = int(lines[1].strip())
            if A in {1,2,3} and B in {1,2,3} and A != B:
                expected = 6 - A - B
                output = int(run(x).strip())
                assert output == expected, f'For valid A={A}, B={B}, output must be {expected}.'
        except ValueError:
            pass  # If A or B not integers, skip.


def test_format(run, x):
    output = run(x)
    # Must be exactly a single digit '1','2','3' followed by a newline, no extra characters before or after.
    import re
    assert re.fullmatch(r'[123]\n', output), "Output must match pattern: single digit 1/2/3 then newline, no extra characters."

def test_distinct(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        try:
            A = int(lines[0].strip())
            B = int(lines[1].strip())
            output = int(run(x).strip())
            assert output != A and output != B, 'Output must be different from both A and B.'
        except ValueError:
            pass  # If A or B not integers, skip.


def test_no_extra_output(run, x):
    output = run(x)
    lines = output.split('\n')
    # Count non-empty lines; there must be exactly one line with content.
    non_empty = [line for line in lines if line.strip() != '']
    assert len(non_empty) == 1, 'Output must contain exactly one line of non-whitespace content.'

def test_consistent_with_choices(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        try:
            A = int(lines[0].strip())
            B = int(lines[1].strip())
            if A in {1,2,3} and B in {1,2,3}:
                output = int(run(x).strip())
                remaining = {1,2,3} - {A, B}
                assert output in remaining, f'Output must be one of the remaining choices: {remaining}.'
        except ValueError:
            pass  # If A or B not integers, skip.

