def test_example3(run, x):
    if x == '3\nxpx\npxp\nxpe\n':
        out = run(x)
        assert out == 'NO\n', f'Example 3 must output NO\n, got {repr(out)}'

def test_x_pattern_implies_yes(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    grid = lines[1:1+n]
    if len(grid) != n:
        return
    # Check X condition
    diag_char = grid[0][0]
    anti_char = grid[0][n-1]
    if diag_char != anti_char:
        return  # Not X pattern
    ok = True
    other_char = None
    for i in range(n):
        for j in range(n):
            ch = grid[i][j]
            if i == j or i == n-1-j:
                if ch != diag_char:
                    ok = False
                    break
            else:
                if other_char is None:
                    other_char = ch
                if ch != other_char or ch == diag_char:
                    ok = False
                    break
        if not ok:
            break
    if ok:
        out = run(x)
        assert out == 'YES\n', f'Grid satisfies X pattern so output must be YES\n, got {repr(out)}'

def test_not_x_pattern_implies_no(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    grid = lines[1:1+n]
    if len(grid) != n:
        return
    # Compute whether grid satisfies X condition
    diag_char = grid[0][0]
    anti_char = grid[0][n-1]
    if diag_char != anti_char:
        not_x = True
    else:
        other_char = None
        ok = True
        for i in range(n):
            for j in range(n):
                ch = grid[i][j]
                if i == j or i == n-1-j:
                    if ch != diag_char:
                        ok = False
                        break
                else:
                    if other_char is None:
                        other_char = ch
                    if ch != other_char or ch == diag_char:
