def test_exactly_one_great_implies_correct(run, x):
    # Compute lengths from x (safe because descriptions are at most 100 chars)
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return  # malformed input, but given inputs are well-formed
    lengths = [len(line.split('.', 1)[1]) for line in lines[:4]]
    # Determine great choices
    greats = []
    for i, L in enumerate(lengths):
        if all(L >= 2 * other for other in lengths if other != L) or all(L <= other / 2 for other in lengths if other != L):
            greats.append(i)
    if len(greats) == 1:
        expected = chr(ord('A') + greats[0])
        output = run(x).strip()
        assert output == expected, f"Exactly one great choice {expected}, got {output}"

