def test_all_same_no(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if not (3 <= n < 300 and n % 2 == 1):
        return
    if len(lines) != n + 1:
        return
    grid = lines[1:]
    if any(len(row) != n for row in grid):
        return
    first = grid[0][0]
    all_same = all(cell == first for row in grid for cell in row)
    if all_same:
        out = run(x).strip()
        assert out == 'NO', f'All letters same, output must be NO, got {out}'

def test_sufficient_condition_yes(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if not (3 <= n < 300 and n % 2 == 1):
        return
    if len(lines) != n + 1:
        return
    grid = lines[1:]
    if any(len(row) != n for row in grid):
        return
    d = grid[0][0]
    # condition (a): both diagonals consist entirely of d
    cond_a = all(grid[i][i] == d for i in range(n)) and all(grid[i][n-1-i] == d for i in range(n))
    if not cond_a:
        return
    # condition (b): d appears exactly 2*n-1 times
    cnt = sum(row.count(d) for row in grid)
    cond_b = cnt == 2 * n - 1
    if not cond_b:
        return
    # condition (c): exactly two distinct letters
    letters = set(''.join(grid))
    cond_c = len(letters) == 2
    if not cond_c:
        return
    # all three hold, so answer must be YES
    out = run(x).strip()
    assert out == 'YES', f'Input satisfies sufficient conditions for YES, but got {out}'

