    # Determine great choices
    great = []
    for i in range(4):
        is_great = True
        for j in range(4):
            if i == j:
                continue
            if not (lengths[i] * 2 <= lengths[j] or lengths[i] >= 2 * lengths[j]):
                is_great = False
                break
        if is_great:
            great.append(chr(ord('A') + i))
    expected = great[0] if len(great) == 1 else 'C'
    out = run(x).strip()
    assert out == expected, f"Expected {expected} based on direct computation, got {out}"

def test_great_choice_consistency(run, x):
    out = run(x).strip()
    if out not in ('A', 'B', 'C', 'D'):
        return  # will be caught by other test
    if out == 'C':
        return  # not required to be great
    idx = ord(out) - ord('A')
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = [len(line) - 2 for line in lines]
    # Check if chosen choice is great
    is_great = True
    for j in range(4):
        if idx == j:
            continue
        if not (lengths[idx] * 2 <= lengths[j] or lengths[idx] >= 2 * lengths[j]):
            is_great = False
            break
    assert is_great, f"Output {out} is not a great choice"

def test_C_when_not_one_great(run, x):
    out = run(x).strip()
    if out != 'C':
        return
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = [len(line) - 2 for line in lines]
    great = []
    for i in range(4):
        is_great = True
        for j in range(4):
            if i == j:
                continue
            if not (lengths[i] * 2 <= lengths[j] or lengths[i] >= 2 * lengths[j]):
                is_great = False
                break
        if is_great:
            great.append(i)
    assert len(great) != 1, f"Exactly one great choice exists, output should be {chr(ord('A')+great[0])}, not C"

