    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = [len(line) - 2 for line in lines]
    if len(set(lengths)) == 1:
        # all lengths equal -> no great choice -> output must be C
        out = run(x).strip()
        assert out == 'C', f"All lengths equal, expected C, got {out}"

