            if i == j:
                continue
            if not (lengths[i] * 2 <= lengths[j] or lengths[i] >= 2 * lengths[j]):
                is_great = False
                break
        if is_great:
            no_great = False
            break
    if no_great:
        out = run(x).strip()
        assert out == 'C', f"No great choice, expected C, got {out}"

def test_exactly_one_great(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = [len(line) - 2 for line in lines]
    great = []
    for i in range(4):
        is_great = True
        for j in range(4):
            if i == j:
                continue
            if not (lengths[i] * 2 <= lengths[j] or lengths[i] >= 2 * lengths[j]):
                is_great = False
                break
        if is_great:
            great.append(i)
    if len(great) == 1:
        expected = chr(ord('A') + great[0])
        out = run(x).strip()
        assert out == expected, f"Exactly one great choice, expected {expected}, got {out}"

